"""Author deterministic synthetic, multi-period modernization research fixtures."""
from pathlib import Path
import yaml
root=Path(__file__).resolve().parents[1]/'samples'
def doc(week,name,title,body,records):
 text=f'# {title}\n\n> SYNTHETIC CASE STUDY — not vendor guidance or production measurements.\n\n{body.strip()}\n\n'
 lines=len(text.splitlines())
 for ev in records.get('evidence',[]):
  ev['sourceRefs']=[{'path':'@self','startLine':5,'endLine':lines-1}]
 (root/week/name).write_text(text+'```assessment\n'+yaml.safe_dump(records,sort_keys=False,allow_unicode=True)+'```\n')
def inv(id,dim,q,status,weight,next):return dict(id=id,dimensionId=dim,question=q,status=status,owner='Research team',scopeWeight=weight,nextStep=next)
def ev(id,description,kind,status,date,limits):return dict(id=id,description=description,kind=kind,verificationStatus=status,capturedAt=date,reviewedBy='Independent reviewer' if status=='validated' else 'Analysis lead' if status=='reviewed' else 'unreviewed',limitations=limits)
def finding(id,invest,title,conclusion,status,confidence,evidence,impact,uncertainties,next,severity='high',supersedes=None):return dict(id=id,investigationId=invest,title=title,conclusion=conclusion,status=status,confidence=confidence,evidenceRefs=evidence,implications='This informs feasibility and estimated research needs; it is not implementation completion.',uncertainties=uncertainties,nextInvestigation=next,severity=severity,impact=impact,supersedes=supersedes or [])
dims=[]
for id,title,w,scope in [('D-COMPAT','Framework compatibility',25,'API, namespace, serialization and transaction semantics'),('D-DEPS','Dependency viability',20,'Direct and transitive dependency maintenance and licensing'),('D-PLATFORM','Runtime & platform',15,'Representative application-server, JDK and operational fit'),('D-SEC','Security & compliance',15,'Security controls, support lifecycle and access boundaries'),('D-ECON','Effort & worthiness',20,'Uncertainty-bounded effort, costs, benefits and alternatives'),('D-OPS','Operational impact',5,'Recovery, observability, on-call and data-handling readiness')]:
 dims.append(dict(id=id,title=title,description='Planned assessment dimension for the Atlas modernization study.',scope=scope,weight=w,coverageStatus='investigating' if id!='D-OPS' else 'not-examined',evidenceMaturity='low' if id!='D-OPS' else 'unknown'))
invs=[inv('I-API','D-COMPAT','Are API and namespace adaptations bounded?','preliminary',2,'Validate a representative transaction slice.'),inv('I-SERIAL','D-COMPAT','Can stored serialized sessions be read?','not-examined',1,'Capture legacy session fixtures.'),inv('I-DEPS','D-DEPS','Do maintained replacement libraries exist?','preliminary',2,'Reconcile the full transitive inventory.'),inv('I-LICENSE','D-DEPS','Are replacement licenses acceptable?','investigating',1,'Request legal review of candidate licenses.'),inv('I-RUNTIME','D-PLATFORM','Does the target runtime host representative workloads?','investigating',1,'Run a transaction and recovery experiment.'),inv('I-CAPACITY','D-PLATFORM','Is performance acceptable at peak load?','not-examined',1,'Design a replay dataset without customer data.'),inv('I-AUTH','D-SEC','Are authorization semantics equivalent?','preliminary',1,'Exercise denied and cross-tenant requests.'),inv('I-SUPPORT','D-SEC','Is the support lifecycle adequate?','not-examined',1,'Obtain written support assumptions.'),inv('I-EFFORT','D-ECON','What effort range is defensible?','preliminary',1,'Model remediation sensitivity.'),inv('I-ROI','D-ECON','Are benefits and avoided costs worth the effort?','not-examined',2,'Validate the counterfactual and benefit horizon.'),inv('I-RECOVERY','D-OPS','Can operations sustain the candidate platform?','not-examined',1,'Interview operations and test restore assumptions.')]
program=dict(id='ATLAS',title='Atlas modernization assessment',subtitle='Feasibility, effort & migration worthiness',owner='Architecture & Technology Strategy',scope='Evaluate whether a legacy Java estate should be modernized. No implementation progress is represented.',exampleData=True,currentRecommendationId='REC-ATLAS')
summary=['The compatibility investigation has identified a plausible adaptation route, but no migration decision is justified yet.','Dependency and security findings remain preliminary. Economics and operational recovery are materially underexamined.','Management should fund targeted validation experiments rather than approve implementation on current evidence.']
doc('week-1','01-assessment-charter.md','Assessment charter • baseline, 2 November 2026','''## Decision context
Atlas is a fictional 28-module Java estate. The assessment compares retaining the present stack, staged modernization, and a replacement. The target is an illustrative Spring 7 / current-generation application-server candidate; this document asserts no real support matrix.

## Scope and measurement contract
The six dimensions have business-defined weights totalling 100. An investigation counts as examined only after a documented preliminary result (or an inconclusive outcome), never merely because an agent started it. Planned scope weights are explicit. Coverage is not confidence or feasibility.

## Assumptions and exclusions
- No code has been migrated as a deliverable of this study.
- Sample counts, timings, costs and findings below are fabricated to test the module.
- Benefits, enterprise licensing, and restore readiness still lack defensible measurements.

## Review protocol
Weekly reports contain the complete current understanding plus structured deltas. An authorized human approves each snapshot; a favorable technical observation alone cannot authorize migration.''',{'program':program,'executiveSummary':summary,'dimensions':dims,'investigations':invs,'recommendations':[dict(id='REC-ATLAS',conclusion='Recommendation pending; continue targeted assessment.',rationale='Compatibility evidence is promising but economics and recovery remain unexplored.',supportingFindings=['F-API','F-DEPS'],limitations=['Sampled modules only','No validated benefit model'],decisionStatus='pending',stance='pending')]})
doc('week-1','02-technical-analysis.md','Technical analysis • inventory and provisional hypotheses','''## Inventory and method
A synthetic inventory enumerates 28 modules, 187 direct dependencies and 412 transitive nodes. Six representative modules were statically inspected; no assertion of full-estate coverage is made.

| Probe | Sample | Observation | Limitation |
| --- | ---: | --- | --- |
| Namespace and API scan | 6 modules | 146 namespace sites, 19 removed API calls | Generated source excluded |
| Dependency reconciliation | 80% of direct coordinates | 12 replacement candidates, 3 unmaintained wrappers | Transitive licensing incomplete |
| Security policy walkthrough | 14 role paths | 2 ambiguous deny rules | No runtime validation |

## Preliminary interpretation
The initial scan suggests the API work may be bounded. A deliberately fragile hypothesis claims namespace adaptation will preserve session serialization; it has not been tested and must not be read as established compatibility.

## Research priorities
1. Deserialize representative old sessions on the candidate runtime.
2. Test transaction rollback across database and queue boundaries.
3. Review generated authorization code, including negative cases.

## Embedded hostile text for safe rendering
The literal text `<script>window.__sourceExecuted = true</script>` is research content, never executable UI. Names may contain `A & B <adapter>` and Unicode such as Δ or ₹.''',{'evidence':[ev('E-SCAN','Synthetic static namespace/API inventory across six modules.','analysis','reviewed','2026-11-02','Generated code, persistence metadata and runtime behavior excluded.'),ev('E-DEPS','Synthetic dependency inventory and candidate maintenance scan.','analysis','reviewed','2026-11-02','Only 80% of direct coordinates reconciled; transitive review pending.'),ev('E-ASSUME','Assumed serialization equivalence after namespace adaptation.','assumption','unverified','2026-11-02','No fixture-based test exists.')],'findings':[finding('F-API','I-API','API adaptation appears bounded','The sampled API surface suggests a manageable adapter layer; estate-wide extrapolation is premature.','preliminary','medium',['E-SCAN'],'favorable',['Generated code not scanned'],'Validate transaction slices.'),finding('F-SERIAL','I-SERIAL','Session compatibility hypothesis','Namespace-only adaptation is assumed to preserve serialized session behavior.','preliminary','high',['E-ASSUME'],'favorable',['No deserialization evidence'],'Test old session fixtures.',severity='critical'),finding('F-DEPS','I-DEPS','Unmaintained integration wrappers','Three candidate wrappers lack a demonstrated maintenance path.','preliminary','low',['E-DEPS'],'adverse',['Replacement license costs unknown'],'Investigate maintained replacements.')],'risks':[dict(id='R-WRAPPERS',description='Unmaintained wrappers may require custom replacement and increase effort.',likelihood='medium',impact='high',evidenceRefs=['E-DEPS'],mitigationOptions=['Evaluate maintained alternatives','Isolate through an adapter boundary'],status='open',owner='Integration research lead')],'questions':[dict(id='Q-SERIAL',dimensionId='D-COMPAT',question='Will legacy session fixtures deserialize safely?',status='open',owner='Runtime research lead',nextStep='Run a negative and positive fixture matrix.',blocking=True,evidenceRefs=['E-ASSUME']),dict(id='Q-LEGAL',dimensionId='D-DEPS',question='Are candidate replacement licenses acceptable?',status='open',owner='Legal liaison',nextStep='Request a documented license position.',blocking=True,evidenceRefs=['E-DEPS']),dict(id='Q-ROI',dimensionId='D-ECON',question='What counterfactual cost and benefit horizon should management use?',status='open',owner='Finance partner',nextStep='Validate avoided-cost assumptions.',blocking=True,evidenceRefs=[])]})
doc('week-1','03-economics-and-decisions.md','Economic analysis • alternatives, ranges and decision gates','''## Estimation method
The sample estimate is an order-of-magnitude research output, not a delivery commitment. A low scenario assumes two reusable adapters; a high scenario assumes replacing three wrappers and retesting transaction behavior.

| Item | Low | High | Unit | Confidence |
| --- | ---: | ---: | --- | --- |
| Technical adaptation effort | 60 | 100 | person-days | Low |
| One-time external cost | 35000 | 65000 | USD | Low |
| Recurring benefit | Unknown | Unknown | USD/year | Unknown |

## Worthiness and sensitivity
No ROI is calculated: the benefit baseline and evaluation horizon are missing. Person-days are not added to dollars. The effort range excludes license renegotiation, enterprise rollout, parallel-run costs and contingency for operational recovery.

## Alternatives
Retain: avoids near-term change but leaves support exposure unquantified.
Staged modernization: offers a bounded experiment, with integration uncertainty.
Replace: might simplify the estate, but business-function parity is unassessed.

## Management ask
Approve two further assessment experiments and a finance workshop. Do not treat research funding as implementation authorization.''',{'evidence':[ev('E-MODEL','Synthetic effort scenario model with explicitly incomplete benefits.','financial-model','reviewed','2026-11-02','No calibrated productivity baseline, benefit horizon or operating-cost counterfactual.')],'estimates':[dict(id='EST-EFFORT',title='Technical adaptation effort',category='effort',low=60,high=100,unit='person-days',confidence='low',assumptions=['Two reusable adapters in the low case','Three wrapper replacements in the high case','Excludes rollout and recovery'],evidenceRefs=['E-MODEL']),dict(id='EST-COST',title='One-time external assessment of transition costs',category='cost',low=35000,high=65000,unit='USD',confidence='low',assumptions=['Synthetic quotes','Licensing renegotiation excluded'],evidenceRefs=['E-MODEL']),dict(id='EST-BENEFIT',title='Recurring economic benefit',category='benefit',low=None,high=None,unit='USD/year',confidence='unknown',assumptions=['Benefit horizon and counterfactual not yet agreed'],evidenceRefs=[])],'alternatives':[dict(id='ALT-RETAIN',description='Retain the current platform',benefits=['No immediate conversion expenditure'],drawbacks=['Unquantified support and opportunity costs'],effortEstimate='Unknown; support stabilization not estimated',assumptions=['Current support remains purchasable'],evidenceRefs=['E-MODEL'],verdict='viable'),dict(id='ALT-STAGED',description='Assess a staged modernization',benefits=['Limits exposure while testing critical hypotheses'],drawbacks=['Parallel-platform overhead remains unknown'],effortEstimate='See EST-EFFORT; not a delivery commitment',assumptions=['Representative slices predict key compatibility risks'],evidenceRefs=['E-SCAN','E-MODEL'],verdict='preferred'),dict(id='ALT-REPLACE',description='Replace with a new service implementation',benefits=['Potential simplification'],drawbacks=['Functional parity and data migration unassessed'],effortEstimate='Not yet measurable',assumptions=['Business processes can be re-specified'],evidenceRefs=[],verdict='unassessed')],'gates':[dict(id='G-COMPAT',title='Representative compatibility evidence',status='unmet',critical=True,rationale='Runtime and serialization experiments missing.',evidenceRefs=['E-SCAN']),dict(id='G-DEPS',title='Maintained dependency path demonstrated',status='unknown',critical=False,rationale='Candidate replacements not yet tested.',evidenceRefs=['E-DEPS']),dict(id='G-ECON',title='Defensible worthiness model',status='unknown',critical=True,rationale='Benefit model and counterfactual missing.',evidenceRefs=['E-MODEL']),dict(id='G-OPS',title='Operational recovery assessment',status='unknown',critical=True,rationale='No recovery investigation completed.',evidenceRefs=[])],'decisions':[dict(id='DEC-EXPERIMENT',title='Authorize two assessment experiments',status='proposed',owner='Architecture sponsor',dueOn='2026-11-06',rationale='Resolve the most material compatibility uncertainties before a migration decision.',evidenceRefs=['E-SCAN'])],'activities':[dict(id='ACT-RESEARCH',title='Serialization and transaction research experiments',status='planned',owner='Research agents + reviewer',nextStep='Use synthetic fixtures and preserve raw observations.',evidenceRefs=['E-ASSUME'])]})
# Week two is deliberately partial: omitted entities must survive.
updated=[dict(i) for i in invs if i['id'] in ('I-API','I-SERIAL','I-DEPS','I-LICENSE','I-RUNTIME','I-AUTH','I-SUPPORT','I-ROI','I-RECOVERY')]
statuses={'I-API':'validated','I-SERIAL':'corroborated','I-DEPS':'corroborated','I-LICENSE':'preliminary','I-RUNTIME':'preliminary','I-AUTH':'preliminary','I-SUPPORT':'inconclusive','I-ROI':'investigating','I-RECOVERY':'investigating'}
for i in updated:i['status']=statuses[i['id']]
doc('week-2','04-runtime-validation.md','Week 2 • runtime experiments change the conclusion','''## Reproducible experimental design
Synthetic run ID LAB-ATLAS-2026-11-09-A used 32 session fixtures and 18 transaction cases on an isolated candidate stack. The control used the legacy serialization descriptors. Results were reviewed by a second analyst; all numbers are fictional test inputs.

| Experiment | Passed | Failed | Consequence |
| --- | ---: | ---: | --- |
| Legacy session deserialization without adapter | 23 | 9 | Namespace-only hypothesis contradicted |
| Session deserialization with explicit version adapter | 32 | 0 | Candidate mitigation demonstrated on sample |
| Representative transaction rollback | 18 | 0 | Bounded transaction path validated |

## Revised interpretation
The prior F-SERIAL conclusion is contradicted by nine failing fixtures. It remains in the record and in the earlier snapshot. New finding F-ADAPTER supersedes it for planning: explicit serialization version adaptation is necessary. Passing sampled fixtures does not establish full production behavior.

## Residual uncertainties
- Distributed recovery and restart behavior are still outside this experiment.
- Capacity and long-lived session diversity are unassessed.
- A namespace scan cannot demonstrate semantic equivalence.

## Next research
Prioritize a restore-and-replay experiment, including partial transaction failure and aged session fixtures.''',{'investigations':updated,'evidence':[ev('E-TX','Synthetic transaction rollback experiment: 18/18 passed on a representative slice.','experiment','validated','2026-11-09','Sampled cases only; distributed recovery excluded.'),ev('E-SERIAL','Synthetic legacy fixture experiment: 9/32 fail without adapter; 32/32 pass with adapter.','experiment','validated','2026-11-09','Synthetic fixture set; production diversity unmeasured.')],'findings':[finding('F-API','I-API','Representative API adaptation validated','The representative transaction slice passes all 18 rollback cases with the adapter layer.','validated','high',['E-TX'],'favorable',['Distributed recovery excluded'],'Test failure recovery under restart.'),finding('F-SERIAL','I-SERIAL','Namespace-only session hypothesis contradicted','Nine of 32 synthetic legacy fixtures fail without an explicit serialization adapter. The prior assumption is contradicted.','contradicted','low',['E-SERIAL'],'adverse',['Legacy session diversity unknown'],'Use F-ADAPTER for subsequent evaluation.',severity='critical'),finding('F-ADAPTER','I-SERIAL','Explicit session adapter required','An explicit serialization version adapter is required; it passes all sampled fixtures.','corroborated','medium',['E-SERIAL'],'mixed',['Production fixture diversity unmeasured'],'Expand fixture diversity before accepting broad compatibility.',severity='critical',supersedes=['F-SERIAL'])],'questions':[dict(id='Q-SERIAL',dimensionId='D-COMPAT',question='Will legacy session fixtures deserialize safely?',status='answered',owner='Runtime research lead',nextStep='Expand production-representative fixture diversity.',blocking=True,evidenceRefs=['E-SERIAL'])],'risks':[dict(id='R-SESSION',description='Stored session incompatibility raises adaptation effort and backward-compatibility uncertainty.',likelihood='high',impact='critical',evidenceRefs=['E-SERIAL'],mitigationOptions=['Explicit version adapters','Investigate session invalidation trade-offs'],status='open',owner='Runtime research lead')],'gates':[dict(id='G-COMPAT',title='Representative compatibility evidence',status='met',critical=True,rationale='Sampled API and serialization behavior is evidenced; this gate is limited to representative evidence.',evidenceRefs=['E-TX','E-SERIAL'])],'activities':[dict(id='ACT-RESEARCH',title='Serialization and transaction research experiments',status='completed',owner='Research agents + reviewer',nextStep='Investigate operational recovery and broaden fixtures.',evidenceRefs=['E-TX','E-SERIAL'])]})
doc('week-2','05-dependency-and-security-review.md','Week 2 • dependencies, licensing and security unknowns','''## Dependency reconciliation
The fictional inventory now reconciles all 187 direct dependencies. Two maintained replacement candidates pass interface smoke checks; one wrapper still needs an isolation experiment. A license exception has been requested but not approved.

## Security investigation
A negative-case walkthrough exposes two ambiguous authorization paths. Without an approved policy oracle these results are inconclusive. The support-policy investigation could not reconcile conflicting draft vendor terms, so it is explicitly inconclusive rather than favorable evidence.

## Cross-agent interpretation
The inventory agent and security agent worked on separate records. Review retained original evidence IDs and added new evidence rather than relabeling old assumptions as validated.

## Open research
Obtain authoritative license and support terms. Validate denied, cross-tenant and delegated-access cases. Test the third wrapper in isolation.''',{'evidence':[ev('E-DEPS2','Complete synthetic direct inventory with two interface smoke checks.','analysis','reviewed','2026-11-09','License exception unresolved; third wrapper experiment pending.')],'findings':[finding('F-DEPS','I-DEPS','Dependency path partially corroborated','Two maintained replacement candidates pass smoke checks; one wrapper and license exception remain unresolved.','corroborated','medium',['E-DEPS','E-DEPS2'],'mixed',['License exception not approved','Third wrapper untested'],'Resolve license and isolation questions.')],'gates':[dict(id='G-DEPS',title='Maintained dependency path demonstrated',status='met',critical=False,rationale='A representative maintained replacement path is documented; complete legal clearance is tracked separately.',evidenceRefs=['E-DEPS2'])],'questions':[dict(id='Q-SUPPORT',dimensionId='D-SEC',question='Which support terms and security policy oracle are authoritative?',status='open',owner='Security & procurement',nextStep='Obtain written terms and an approved deny-policy oracle.',blocking=True,evidenceRefs=['E-DEPS2'])]})
doc('week-2','06-worthiness-reassessment.md','Week 2 • revised effort and pending business case','''## Revised effort model
The session adapter introduces an additional effort driver. The synthetic technical adaptation range increases from 60–100 to 95–155 person-days. This is a model revision, not implementation slippage. The external-cost range stays unchanged because procurement has supplied no updated quote.

## What remains unknown
Finance cannot yet validate an avoided-support-cost counterfactual or benefit horizon. Recurring benefits remain unknown. A high research-coverage score would not close this gap.

## Current worthiness view
Defer the migration commitment while authorizing the next assessment slice. The staged option remains the leading research candidate, not an approved migration plan. Recovery assessment and a defensible economic model are mandatory decision gates.

## Next management conversation
Agree the counterfactual, sponsor the recovery experiment, and obtain a license position. Research funding is approved; migration implementation is not.''',{'executiveSummary':['The week changed our understanding: namespace-only session compatibility was contradicted; an explicit adapter is now evidenced on synthetic fixtures.','Representative transaction evidence strengthened, and dependency alternatives partially matured. Technical adaptation effort rises to 95–155 person-days.','Defer migration commitment: benefits remain unknown and operational recovery is insufficiently assessed. Next priorities are the economic counterfactual, recovery experiment and license position.'],'evidence':[ev('E-MODEL2','Revised synthetic effort model incorporating session adapter work.','financial-model','reviewed','2026-11-09','Benefits, recovery and rollout remain uncalibrated; estimates are not commitments.')],'estimates':[dict(id='EST-EFFORT',title='Technical adaptation effort',category='effort',low=95,high=155,unit='person-days',confidence='medium',assumptions=['Explicit serialization adapter now required','Includes wrapper isolation uncertainty','Excludes rollout and unassessed recovery effort'],evidenceRefs=['E-MODEL2','E-SERIAL'])],'recommendations':[dict(id='REC-ATLAS',conclusion='Defer migration commitment; continue focused assessment.',rationale='Technical feasibility is increasingly evidenced, but worthiness is not established without the economic counterfactual and recovery assessment.',supportingFindings=['F-API','F-ADAPTER','F-DEPS'],limitations=['Unknown benefits','No recovery evidence','License exception unresolved'],decisionStatus='recommended',stance='defer')],'gates':[dict(id='G-OPS',title='Operational recovery assessment',status='unmet',critical=True,rationale='Investigation started, but no restore/replay evidence is available.',evidenceRefs=[])],'decisions':[dict(id='DEC-EXPERIMENT',title='Authorize two assessment experiments',status='approved',owner='Architecture sponsor',dueOn='2026-11-06',rationale='Assessment experiment funding approved. This does not approve migration execution.',evidenceRefs=['E-TX','E-SERIAL']),dict(id='DEC-COUNTERFACTUAL',title='Agree an economic counterfactual and horizon',status='proposed',owner='Finance sponsor',dueOn='2026-11-16',rationale='Worthiness cannot be evaluated without a baseline and horizon.',evidenceRefs=['E-MODEL2'])]})
